SET NOCOUNT ON;
SELECT 'Usuarios' Tabla,COUNT(*) Cantidad FROM dbo.Usuarios UNION ALL SELECT 'Empleados',COUNT(*) FROM dbo.Empleados UNION ALL SELECT 'Pedidos',COUNT(*) FROM dbo.Pedidos UNION ALL SELECT 'DetallePedido',COUNT(*) FROM dbo.DetallePedido UNION ALL SELECT 'Pagos',COUNT(*) FROM dbo.Pagos UNION ALL SELECT 'CorreoEnvios',COUNT(*) FROM dbo.CorreoEnvios UNION ALL SELECT 'EML',0;
SELECT o.name, o.type_desc, HAS_PERMS_BY_NAME(QUOTENAME(SCHEMA_NAME(o.schema_id))+'.'+QUOTENAME(o.name),'OBJECT','EXECUTE') AS ExecuteEffective FROM sys.objects o WHERE o.name IN ('app_DatosCorreoPedido','app_ActualizarPagoSeguro','app_EncolarComprobantePago');
SELECT OBJECT_SCHEMA_NAME(major_id)+'.'+OBJECT_NAME(major_id) Objeto,dp.name Principal,p.permission_name,p.state_desc FROM sys.database_permissions p JOIN sys.database_principals dp ON dp.principal_id=p.grantee_principal_id WHERE OBJECT_NAME(major_id) IN ('app_DatosCorreoPedido','app_ActualizarPagoSeguro','app_EncolarComprobantePago');
